INSERT INTO blog_categories (id, slug, name, description, icon_name, accent_color, banner_gradient, display_order, is_active) VALUES (1, 'dinh-huong-nghe-nghiep', 'Định hướng nghề nghiệp', 'Cẩm nang định hướng phát triển sự nghiệp toàn diện: Giúp bạn thấu hiểu bản thân theo mô hình Ikigai, chọn ngành nghề phù hợp với xu hướng tuyển dụng 2026 và xây dựng lộ trình thăng tiến bền vững.', 'Compass', '#00b14f', 'from-emerald-600 via-teal-600 to-emerald-800', 1, TRUE) ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), accent_color = VALUES(accent_color);
INSERT INTO blog_categories (id, slug, name, description, icon_name, accent_color, banner_gradient, display_order, is_active) VALUES (2, 'bi-kip-tim-viec', 'Bí quyết tìm việc', 'Bộ cẩm nang thực chiến chinh phục nhà tuyển dụng từ A-Z: Hướng dẫn tối ưu hóa CV vượt qua bộ lọc ATS trong 6 giây, kịch bản trả lời 50+ câu hỏi phỏng vấn hóc búa và nghệ thuật deal lương cao hơn 20-30%.', 'Briefcase', '#2563eb', 'from-blue-600 via-indigo-600 to-blue-800', 2, TRUE) ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), accent_color = VALUES(accent_color);
INSERT INTO blog_categories (id, slug, name, description, icon_name, accent_color, banner_gradient, display_order, is_active) VALUES (3, 'che-do-luong-thuong', 'Chế độ hưởng lương', 'Hiểu rõ quyền lợi tài chính và pháp lý của bạn theo Bộ luật Lao động mới nhất: Công cụ tính lương Gross sang Net chuẩn quy định bảo hiểm xã hội (BHXH, BHYT, BHTN), biểu thuế TNCN lũy tiến và cách tính thưởng tháng 13.', 'Calculator', '#ea580c', 'from-amber-600 via-orange-600 to-amber-800', 3, TRUE) ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), accent_color = VALUES(accent_color);
INSERT INTO blog_categories (id, slug, name, description, icon_name, accent_color, banner_gradient, display_order, is_active) VALUES (4, 'kien-thuc-chuyen-nganh', 'Kiến thức chuyên ngành', 'Đào sâu kiến thức chuyên môn thực chiến và bắt kịp xu hướng thị trường lao động 2026: Phân tích chuyên sâu nghiệp vụ Marketing, Công nghệ thông tin / AI, Logistics, Tài chính ngân hàng và Quản trị nhân sự.', 'GraduationCap', '#7c3aed', 'from-violet-600 via-purple-600 to-violet-800', 4, TRUE) ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), accent_color = VALUES(accent_color);
